XWiki.locale = document.documentElement.getAttribute('lang') || '';

define('xwiki-ckeditor', [
  'jquery',
  // The CKEditor standard API.
  'ckeditor',
  // Used to access the form token required by the upload URL.
  'xwiki-meta',
  // CKEditor plugins specific to XWiki.
  'xwiki-ckeditor-plugins',
  // Used to catch form action events fired from Prototype.js code (actionButtons.js).
  'xwiki-events-bridge',
  // Load the translations for our custom CKEditor plugins.
  new XWiki.Document('Translations', 'CKEditor').getURL('jsx', 'language=' + encodeURIComponent(XWiki.locale))
], function($, ckeditor, xwikiMeta) {
  // CKEditor creates an editor for each element marked as editable when the page is loaded, unless we disable it. Our
  // editors make the edited content editable, possibly before the page is loaded.
  ckeditor.disableAutoInline = true;

  // We have to pass the plugin that makes the request (the initiator) because the expected response can be different
  // (e.g. between the filebrowser and filetools plugins).
  var getUploadURL = function(document, initiator) {
    return document.getURL('get', $.param({
      sheet: 'XWiki.WYSIWYG.FileUploader',
      outputSyntax: 'plain',
      // The syntax and language are important especially when the upload request creates a new document.
      syntax: document.syntax,
      language: XWiki.locale,
      form_token: xwikiMeta.form_token,
      initiator: initiator
    }));
  };

  // Extend the default CKEditor configuration with settings that depend on the source document.
  var getConfig = function(element) {
    var sourceSyntax = $(element).attr('data-syntax');
    var sourceDocument = XWiki.currentDocument;
    sourceDocument.syntax = XWiki.docsyntax;
    var sourceDocumentReference = XWiki.Model.resolve($(element).attr('data-sourceDocumentReference'),
      XWiki.EntityType.DOCUMENT, XWiki.currentDocument.documentReference);
    if (!XWiki.currentDocument.documentReference.equals(sourceDocumentReference)) {
      sourceDocument = new XWiki.Document(sourceDocumentReference);
      // We assume the syntax of the source document is the same as the syntax of the edited content.
      sourceDocument.syntax = sourceSyntax;
    }

    var uploadDisabled = element.hasAttribute('data-upload-disabled');
    var startupFocus = element.hasAttribute('data-startup-focus');

    var config = {
      filebrowserUploadUrl: uploadDisabled ? '' : getUploadURL(sourceDocument, 'filebrowser'),
      startupFocus,
      height: $(element).height(),
      // Used to resolve and serialize relative references. Also used to make HTTP requests with the right context.
      sourceDocument: sourceDocument,
      // The syntax of the edited content is not always the same as the syntax of the source document (which applies to
      // the source document content, but we might be editing something else, like an object property).
      sourceSyntax: sourceSyntax,
      uploadUrl: uploadDisabled ? '' : getUploadURL(sourceDocument, 'filetools'),
      'xwiki-link': {
        // We use the source document to compute the link label generator URL because we want the link references to be
        // resolved relative to the edited document (as they were inserted).
        labelGenerator: sourceDocument.getURL('get', $.param({
          sheet: 'XWiki.WYSIWYG.LinkLabelGenerator',
          outputSyntax: 'plain',
          language: XWiki.locale
        }))
      }
    };
    return config;
  };

  var oldReplace = ckeditor.replace;
  ckeditor.replace = function(element, config) {
    // Take into account the configuration options specified on the target element.
    return oldReplace.call(this, element, ckeditor.tools.extend(getConfig(element), config, true));
  };

  var oldInline = ckeditor.inline;
  ckeditor.inline = function(element, config) {
    // CKEditor shows the value of a text area as is in the page until the editor is loaded, without filtering it, and
    // this value can be wiki syntax (e.g. restored by the browser in Source mode) which must not be parsed as HTML.
    var textArea = ckeditor.dom.element.get(element);
    textArea = textArea?.is('textarea') ? textArea.$ : null;
    var value = textArea?.value;
    if (textArea) {
      textArea.value = '';
    }
    try {
      // Take into account the configuration options specified on the target element.
      var editor = oldInline.call(this, element, ckeditor.tools.extend(getConfig(element), config, true));
    } finally {
      if (textArea) {
        textArea.value = value;
      }
    }
    if (textArea && editor) {
      // The editor filters the data it is given when it loads.
      editor.setData(value, null, true);
    }
    return editor;
  };

  //
  // Overwrite in order to add support for configuration namespaces.
  //
  ckeditor.tools.extend = function(target) {
    var argsLength = arguments.length, overwrite, propertiesList;
    if (typeof (overwrite = arguments[argsLength - 1]) === 'boolean') {
      argsLength--;
    } else if (typeof (overwrite = arguments[argsLength - 2]) === 'boolean') {
      propertiesList = arguments[argsLength - 1];
      argsLength -= 2;
    }
    for (var i = 1; i < argsLength; i++) {
      var source = arguments[i] || {};
      ckeditor.tools.array.forEach(ckeditor.tools.object.keys(source), function(propertyName) {
        // Only copy existing fields if in overwrite mode.
        if (overwrite === true || target[propertyName] == null) {
          // Only copy specified fields if list is provided.
          if (!propertiesList || (propertyName in propertiesList)) {
            // NOTE: This is the only part we overwrite.
            setObjectProperty(target, propertyName, source[propertyName]);
          }
        }
      });
    }
    return target;
  };

  var setObjectProperty = function(object, key, value) {
    var oldValue = object[key];
    var newValue = value;
    // Merge the old value with the new value if both are objects and the old value is a configuration namespace.
    if ($.isPlainObject(oldValue) && oldValue.__namespace === true && $.isPlainObject(newValue)) {
      // We don't modify directly the old value because it may be inherited (e.g. global configuration).
      newValue = ckeditor.tools.extend({}, oldValue, newValue, true);
    }
    object[key] = newValue;
  };

  // See XWIKI-21351: Macros using RequireJS are not properly displayed by the standalone WYSIWYG editor even when
  // JavaScript is enabled.
  //
  // For each CKEditor instance that uses a separate DOM document for the edited content (i.e. classical iframe-based
  // editor) we overwrite the appendChild and insertBefore functions of the initial HEAD element in order to make sure
  // that RequireJS appends the script tags to the current HEAD element (because the HEAD element is overwritten each
  // time the edited content is reloaded, like when inserting a macro or switching between Source and WYSIWYG modes).
  //
  // We have to overwrite both appendChild and insertBefore because depending on the presence of the BASE element
  // RequireJS uses one or the other.
  ckeditor.on('instanceReady', ({editor}) => {
    if (editor.mode === 'wysiwyg' && editor.document.$ !== document) {
      // This editor instance is using a separate DOM document for editing which means it's a classic (iframe-based)
      // editor.
      const initialHead = editor.document.$.head;
      const originalAppendChild = initialHead.appendChild;
      initialHead.appendChild = function() {
        const currentHead = editor.document.$.head;
        if (currentHead !== initialHead) {
          // The edited content has been reloaded. Append to the current HEAD.
          return currentHead.appendChild.apply(currentHead, arguments);
        } else {
          // Still using the initial HEAD so preserve the default behavior.
          originalAppendChild.apply(initialHead, arguments);
        }
      };
      const originalInsertBefore = initialHead.insertBefore;
      initialHead.insertBefore = function(newChild, existingChild) {
        const currentHead = editor.document.$.head;
        if (currentHead !== initialHead) {
          // The edited content has been reloaded. Normally the given existingChild should be a child of the initial
          // HEAD element (not the current one), but better check to be sure.
          if (existingChild.parentNode === currentHead) {
            return currentHead.insertBefore(newChild, existingChild);
          } else {
            return currentHead.appendChild.apply(newChild);
          }
        } else {
          // Still using the initial HEAD so preserve the default behavior.
          return originalInsertBefore.apply(initialHead, arguments);
        }
      };
    }
  });

  function startAvoidingCKAndSaveBarOverlap(editor) {
    // CKEDITOR-470 - CKEditor's toolbar may overlap with XWiki's save bar.
    // This function is a workaround that checks if they overlap when the page
    // is scrolled and when the CKEditor's toolbar's CSS style is changed
    // Ideally, we would cooperate with CKEditor's code to position its toolbar,
    // but the toolbar position is not customizable.
    //
    // The CKEditor toolbar (the floatSpace variable) is positioned by this code:
    // https://github.com/ckeditor/ckeditor4/blob/19a386c4691a99d37b43e876e5f5a7ce092c6016/plugins/floatingspace/plugin.js#L100
    //
    // This happens when the editor gains focus, when some text is typed (the
    // editor's content changes), when the window is scrolled or when the window
    // is resized.
    // See https://github.com/ckeditor/ckeditor4/blob/19a386c4691a99d37b43e876e5f5a7ce092c6016/plugins/floatingspace/plugin.js#L310

    function avoidCKAndSaveBarOverlap() {
      // This callback will be called when the page is scrolled or when the
      // CKEditor's toolbar position is changed.

      const ckBRC = ckFloatingToolbar.getBoundingClientRect();
      const saveBRC = saveBar.getBoundingClientRect();
      // Compare with the save bar position without the room we left for the toolbar, otherwise the collision would
      // disappear as soon as we leave the room, and we would remove it.
      const collision = ckBRC.top + ckBRC.height > saveBRC.top - roomForToolbar;
      if (saveBar.classList.contains("sticky-buttons-fixed")) {
          // If XWiki's save bar is sticky, it should not have our custom
          // margin-top.
          removeRoomForToolbar();

          if (collision) {
            // If there is a collision, CKEditor decided to place the toolbar at
            // the bottom. This is the chosen position if:
            // - the height of the CKEditor toolbar is not greater than the top of
            //   the editor relative to the viewport, and
            // - the height of the CKEditor toolbar is not greater than the
            //   difference between the bottom of the editor relative to the
            //   viewport and its height
            // We put the CKEditor toolbar at the top of the viewport.
            // Note that CKEditor will try to revert this on the events
            // previously listed but we will force the position back again
            // immediately thanks to the mutation observer. This does not
            // trigger an event that makes CKEditor position the toolbar once
            // again, so we are not racing with it.

            ckFloatingToolbar.style.position = "fixed";
            ckFloatingToolbar.style.top = "0px";
          }
      } else {
        // If the XWiki's save bar is not sticky, we add a margin-top
        // corresponding to the CKEditor toolbar's height if there is a
        // collision, and we revert to the initial margin-top if there is no
        // collision.
        if (collision) {
          if (!roomForToolbar) {
            roomForToolbar = ckBRC.height;
            saveBar.style.marginTop = (parseInt(getComputedStyle(saveBar).getPropertyValue('margin-top')) +
              roomForToolbar) + 'px';
          }
        } else {
          removeRoomForToolbar();
        }
      }
    }

    let roomForToolbar = 0;
    function removeRoomForToolbar() {
      if (roomForToolbar) {
        saveBar.style.marginTop = '';
        roomForToolbar = 0;
      }
    }

    const ckFloatingToolbar = document.getElementById('cke_' + editor.name);
    // The save bar of the in-place edit mode, or of the standalone edit mode.
    const saveBar = document.getElementsByClassName('inplace-editing-buttons')[0] ||
      document.getElementsByClassName('bottombuttons')[0];
    // The toolbar of the other editors (e.g. of a form field) is not floating.
    if (ckFloatingToolbar?.classList.contains('cke_float') && saveBar) {
      window.addEventListener("scroll", avoidCKAndSaveBarOverlap);
      const mutationObserver = new MutationObserver(avoidCKAndSaveBarOverlap);
      mutationObserver.observe(ckFloatingToolbar, {
        attributes: true,
        attributeFilter: ['style']
      });

      return function stopAvoidingCKAndSaveBarOverlap() {
        window.removeEventListener("scroll", avoidCKAndSaveBarOverlap);
        mutationObserver.disconnect();
        removeRoomForToolbar();
      };
    }

    return null;
  }
  ckeditor.on('instanceReady', ({editor}) => {
    const stopAvoidingCKAndSaveBarOverlap = startAvoidingCKAndSaveBarOverlap(editor);
    if (stopAvoidingCKAndSaveBarOverlap) {
      editor.once('destroy', stopAvoidingCKAndSaveBarOverlap);
    }
  });

  return $.Deferred().resolve(ckeditor).promise();
});

require(['jquery', 'xwiki-ckeditor', 'xwiki-events-bridge'], function($, ckeditorPromise) {
  // Make sure we don't create the editors twice because this file can be loaded twice (by RequireJS, for in-place
  // editing, and as a JSX resource, for standalone editing).
  if (ckeditorPromise.__editSheetLoaded) {
    return;
  }
  ckeditorPromise.__editSheetLoaded = true;

  var createEditors = function(ckeditor, container) {
    container.find('.ckeditor-textarea').each(function() {
      // Wrap in try/catch so that a failure to load one editor doesn't affect the other editors.
      try {
        createEditor(ckeditor, this).then(() => {
          this.classList.remove('loading');
        });
      } catch(e) {
        console.log(e);
      }
    });
  };

  // Sets the height of the editing area, padding included (its height style doesn't include the padding).
  var setEditingAreaHeight = function(editor, height) {
    var style = window.getComputedStyle(editor.container.$);
    var padding = parseFloat(style.paddingTop) + parseFloat(style.paddingBottom);
    editor.container.setStyle('height', Math.max(0, height - padding) + 'px');
  };

  // The floating tool bar of the main field is shown above the edited content while editing. While it's shown, leave
  // room for it, so that it doesn't cover what's above (e.g. the page title), and scroll the page by the same amount,
  // so that the edited content doesn't move (what's above goes out of view instead).
  var leaveRoomForToolBar = function(editor) {
    var toolBar = document.getElementById('cke_' + editor.name);
    if (!toolBar) {
      return;
    }
    // Set on the parent of the text area, so that it applies to all editing modes (WYSIWYG, Source).
    var parent = editor.element.getParent().$;
    var room = 0;
    var setRoom = function(height) {
      if (height !== room) {
        parent.style.setProperty('--ckeditor-toolbar-height', height + 'px');
        window.scrollBy(0, height - room);
        room = height;
      }
    };
    // Measure the hidden tool bar where it's going to be shown, since its buttons wrap. Priority 1 runs this before the
    // floatingspace plugin shows it.
    editor.on('focus', function() {
      if (toolBar.style.display === 'none') {
        $(toolBar).css({display: '', visibility: 'hidden', left: $(editor.container.$).offset().left + 'px'});
        var height = toolBar.offsetHeight;
        $(toolBar).css({display: 'none', visibility: '', left: ''});
        setRoom(height);
      }
    }, null, null, 1);
    var resizeObserver = new ResizeObserver(function() {
      setRoom(toolBar.offsetHeight);
    });
    resizeObserver.observe(toolBar);
    editor.once('destroy', function() {
      resizeObserver.disconnect();
    });
  };

  // The main field (e.g. the page content) takes all the available height, without making the page scroll, so that the
  // user can click anywhere below the content to edit it.
  var fillAvailableHeight = function(editor) {
    // Set on the parent of the text area, so that it applies to all editing modes (WYSIWYG, Source).
    var parent = editor.element.getParent().$;
    var update = function() {
      var editingArea = editor.container.$;
      var toolBarRoom = parseFloat(window.getComputedStyle(editingArea).marginTop) || 0;
      // The scroll height of the root element is never less than the viewport height, so use the height of the page
      // content, including what overflows the body, rounded up to avoid a scroll bar.
      var pageHeight = Math.ceil(Math.max(document.documentElement.getBoundingClientRect().height,
        document.body.scrollHeight));
      // The current minimum height is part of the editing area height, so we don't need to remove it first (which would
      // make the page jump).
      var minHeight = Math.floor(editingArea.offsetHeight + document.documentElement.clientHeight - pageHeight +
        toolBarRoom);
      parent.style.setProperty('--ckeditor-main-field-min-height', Math.max(0, minHeight) + 'px');
    };
    update();
    var namespace = 'resize.ckeditorFill_' + editor.name;
    $(window).on(namespace, update);
    editor.on('modeReady', update);
    editor.once('destroy', function() {
      $(window).off(namespace);
    });
  };

  // The edited content is inside the form, so the form fields that macros output in it (e.g. Live Data filters) would
  // be submitted with the form. A disabled field set disables all the form fields it contains.
  var disableFormFieldsInContentOnSubmit = function(editor, editingArea) {
    var textArea = editor.element.$;
    var fieldSet = document.createElement('fieldset');
    fieldSet.className = 'ckeditor-content';
    var wrap = function(element) {
      element.before(fieldSet);
      fieldSet.append(element);
    };
    wrap(editingArea[0]);
    // The WYSIWYG editing area is put back where the other modes (e.g. Source) were shown.
    editor.on('contentDom', function() {
      if (editor.container.$.parentNode !== fieldSet) {
        wrap(editor.container.$);
      }
    });
    // The other modes have no such form fields, so show them outside the field set, which keeps the hidden WYSIWYG
    // editing area. Priority 20 runs this after the WYSIWYG editing area is replaced, when leaving the WYSIWYG mode.
    editor.on('beforeModeUnload', function() {
      if (editor.mode === 'wysiwyg') {
        fieldSet.after(editor.container.$);
      }
    }, null, null, 20);
    var disableFormFields = function(event, data) {
      // Some code fires these events without the form (e.g. when switching editors), or on the whole document.
      var form = data?.form || $(event.target).closest('form')[0];
      if (!form || form === textArea.form) {
        fieldSet.disabled = true;
        // The form data is collected right after these events, whether the form is submitted or not.
        setTimeout(function() {
          fieldSet.disabled = false;
        }, 0);
      }
    };
    var events = 'xwiki:actions:beforeSave xwiki:actions:beforePreview';
    $(document).on(events, disableFormFields);
    // The buttons in the edited content (e.g. output by macros) would submit the whole form, i.e. save the page.
    var preventSubmitFromContent = function(event) {
      if (event.target === textArea.form && fieldSet.contains(event.submitter)) {
        event.preventDefault();
      }
    };
    textArea.form?.addEventListener('submit', preventSubmitFromContent);
    editor.once('destroy', function() {
      $(document).off(events, disableFormFields);
      textArea.form?.removeEventListener('submit', preventSubmitFromContent);
      // CKEditor removes the editing area but not the field set we added around it.
      fieldSet.remove();
    });
  };

  var createEditor = function(ckeditor, textArea, instanceConfig) {
    var deferred = $.Deferred();
    var config = {};
    var isMainField = $(textArea).is('.ckeditor-main-field, .ckeditor-main-field *');
    if (isMainField) {
      // Main field (e.g. page content): floating tool bar.
      config.resize_enabled = false;
      // Dock the tool bar a bit above the edited content, so that it doesn't cover the drag handle of a widget on the
      // first line (shown above the widget).
      config.floatSpaceDockedOffsetY = 15;
    } else {
      // Other fields (e.g. comments, object properties): fixed tool bar and bottom bar.
      var field = $(textArea).parent('.ckeditor-field');
      if (!field.length) {
        field = $(textArea).wrap('<div class="ckeditor-field"></div>').parent();
        // Show as many lines of text as the text area (whose height is given by its number of rows).
        field.css('--ckeditor-field-height', textArea.rows + 'lh');
      }
      // The sharedspace plugin hides the tool bar it adds to a container that a previous editor of the field (e.g.
      // before a syntax change) already used, so we use new containers.
      field.children('.ckeditor-field-top, .ckeditor-field-bottom').remove();
      field.prepend('<div class="ckeditor-field-top"></div>');
      field.append('<div class="ckeditor-field-bottom"></div>');
      config.sharedSpaces = {
        top: field.children('.ckeditor-field-top')[0],
        bottom: field.children('.ckeditor-field-bottom')[0]
      };
    }
    var editor = ckeditor.inline(textArea, $.extend(config, instanceConfig));
    var editingArea = $(textArea).next('.cke_textarea_inline');
    if (isMainField) {
      // The skin styles the content edited in a form (e.g. its links) like the content in view mode.
      editingArea.addClass('xwiki-content');
    }
    disableFormFieldsInContentOnSubmit(editor, editingArea);
    if (config.resize_enabled !== false) {
      // The default implementation only resizes the iframe of the classic editor.
      editor.resize = function(width, height) {
        setEditingAreaHeight(editor, height);
        editor.fire('resize', {outerHeight: height, contentsHeight: height});
      };
      // The resize plugin keeps the element it gets the first time, but the editing area changes with the editing mode,
      // so give it the size of the current one.
      editor.getResizable = function() {
        return {$: {
          get offsetWidth() {
            return editor.container.$.offsetWidth;
          },
          get offsetHeight() {
            return editor.container.$.offsetHeight;
          }
        }};
      };
      // Keep the height of the editing area, which the user can resize, when switching between WYSIWYG and Source.
      var editingAreaHeight;
      editor.on('beforeModeUnload', function() {
        // The full-screen height is not the one the user chose.
        if (editor.getCommand('maximize')?.state !== CKEDITOR.TRISTATE_ON) {
          editingAreaHeight = editor.container.$.offsetHeight;
        }
      });
      editor.on('modeReady', function() {
        if (editingAreaHeight) {
          setEditingAreaHeight(editor, editingAreaHeight);
        }
      });
    }
    editor.once('instanceReady', function() {
      if (isMainField) {
        leaveRoomForToolBar(editor);
        fillAvailableHeight(editor);
      }
      deferred.resolve(editor);
    });
    editor.once('reload', function(event) {
      event.data.promise = event.data.promise.then(createEditor.bind(null, ckeditor, textArea));
    });
    return deferred.promise();
  };

  ckeditorPromise.done(function(ckeditor) {
    createEditors(ckeditor, $(body));
    // Make sure we don't register the event listener multiple times (in case this code is loaded multiple times).
    $(document).off('xwiki:dom:updated.ckeditor').on('xwiki:dom:updated.ckeditor', function(event, data) {
      createEditors(ckeditor, $(data.elements));
    });
  });
});

a.cke_button_disabled > span.cke_button_icon.loading {
  background-image: url(@xwiki-icon-spinner) !important;
  background-position: 0 0 !important;
}

.ckeditor-textarea.loading {
  border: 0 none;
  box-shadow: none;
  color: transparent;
  cursor: wait;
  overflow: hidden;
  resize: none;
}

/* Hide the form action bar while the editor is loading in order to avoid UI flickering (because the editor may enhance
  or replace the form action bar). */
main > div:has(.ckeditor-textarea.loading) ~ .bottom-editor,
#xwikicontent.loading ~ form#inplace-editing {
  visibility: hidden;
}

/* Show the modal above the CKEditor dialogs */
body > .modal-backdrop {
  z-index: 10040;
}
/* The modal can be nested inside the body while the backdrop is always a direct child of body. */
body .modal {
  z-index: 10050;
}

/* The div that CKEditor adds next to the text area, to edit its content. */
.cke_textarea_inline {
  outline: 0;
}

/* The field set added around the editing area, only to disable the form fields it contains, has no layout. */
fieldset.ckeditor-content {
  display: contents;
}

/* The page content has no border, so the save bar below it has its own full border. */
main > div:has(#xwikieditcontent .cke_textarea_inline)
    ~ .bottom-editor > .sticky-buttons:not(.sticky-buttons-fixed) {
  border-top: @border-width solid @input-border;
  border-radius: @border-radius-base;
  margin-top: @line-height-computed;
}

/* In all editing modes, the main field (e.g. the page content) leaves room for its floating tool bar and takes all the
  available height, both computed by the loader. */
.cke_textarea_inline,
.cke_contents.fake {
  margin-top: ~"var(--ckeditor-toolbar-height, 0)";
  min-height: ~"var(--ckeditor-main-field-min-height, 0)";
}

/* Keep the margins of the first and last children (e.g. a heading) inside the edited content, so that they don't merge
  with the room left for the tool bar, and so that the edited content starts where the user caret indicators expect. */
.cke_textarea_inline {
  display: flow-root;
}

/* In full-screen mode the parent of the edited content is maximized (see the xwiki-realtime plugin), so the edited
  content fills it, below the tool bar. */
.cke_editable_active > .ckeditor-content > .cke_textarea_inline {
  box-sizing: border-box;
  margin-top: 0;
  min-height: 100%;
}

/* The fields other than the main one (e.g. comments, object properties) have the border of a form field, around their
  tool bar, content and bottom bar. */
.ckeditor-field {
  border: @border-width solid @input-border;
  border-radius: @input-border-radius;
  .box-shadow(inset 0 1px 1px rgba(0, 0, 0, .075));

  /* Same as .form-control-focus(), which applies only to :focus. */
  &:focus-within {
    @color-rgba: rgba(red(@input-border-focus), green(@input-border-focus), blue(@input-border-focus), .6);
    border-color: @input-border-focus;
    outline: 0;
    .box-shadow(~"inset 0 1px 1px rgba(0, 0, 0, .075), 0 0 8px @{color-rgba}");
  }

  /* The height of the text area content, computed by the loader. */
  & > .ckeditor-content > .cke_textarea_inline,
  & > .cke_contents {
    box-sizing: content-box;
    height: ~"var(--ckeditor-field-height)";
    margin-top: 0;
    min-height: 3em;
    overflow-y: auto;
  }

  & > .ckeditor-content > .cke_textarea_inline {
    padding: @padding-base-vertical @padding-base-horizontal;
  }

  /* The field has the border. */
  .cke_chrome {
    border: 0 none;
    box-shadow: none;
    padding: 0;
  }

  .cke_top {
    border-radius: @input-border-radius @input-border-radius 0 0;
  }

  .cke_bottom {
    border-radius: 0 0 @input-border-radius @input-border-radius;
  }

  /* In full-screen mode the field fills the space between the tool bar and the form action buttons. */
  &.cke_editable_active {
    border: 0;
    border-radius: 0;
    box-shadow: none;
    display: flex;
    flex-direction: column;

    & > .ckeditor-content > .cke_textarea_inline,
    & > .cke_contents {
      flex: 1;
      /* Overwrite the height set when the field is resized. */
      height: auto !important;
    }
  }
}

/**
 * Full-screen styles
 */

.fullScreenEditLinkContainer {
  /* See XWIKI-5864 (Possibility to not add the maximize button for some certain textareas). */
  display: none;
}

/* The form buttons that the classic (iframe-based) editor moves inside it in full-screen mode. */
.cke_maximized .buttons {
  background-color: @well-bg;
  padding: .5em;
}

/* Make sure the notifications (e.g. for Save & Continue action) and the modals (e.g. for expired session) are visible
  when editing in full-screen mode. */
body[data-maximized] .xnotification-container,
body[data-maximized] .xdialog-modal-container {
  z-index: 9996;
}

/**
 * Resource Picker Styles
 * We duplicate a couple of Bootstrap styles because CKEditor resets the styles of all the dialog elements.
 */
.resourcePicker.input-group {
  border-collapse: separate;
  position: relative;
}

.resourcePicker input[type="text"] {
  box-sizing: border-box;
  padding: 6px;
}

.resourcePicker .input-group-btn {
  font-size: 0;
  position: relative;
  vertical-align: middle;
  width: 1%;
}

.resourcePicker .btn-default {
  color: #333;
  cursor: pointer;
  border: 1px solid #CCC;
  font-size: 14px;
  line-height: 1.428571429;
  padding: 6px 12px;
  text-align: center;
  vertical-align: middle;
}

.resourcePicker .btn-default:hover,
.resourcePicker .btn-default:focus {
  background-color: #E6E6E6;
  background-image: none;
}

.resourcePicker .btn-default[disabled] {
  cursor: default;
}

.resourcePicker .caret {
  border-right: 4px solid transparent;
  border-left: 4px solid transparent;
  border-top: 4px dashed;
  border-top: 4px solid;
  height: 0;
  vertical-align: middle;
  width: 0;
}

.resourcePicker .dropdown-toggle {
  padding: 6px;
}

.resourcePicker .dropdown-menu {
  background-clip: padding-box;
  background-color: white;
  border: 1px solid #CCC;
  border: 1px solid rgba(0, 0, 0, 0.15);
  float: left;
  font-size: 14px;
  margin: 2px 0 0;
  padding: 5px 0;
  position: absolute;
}

/* Overwrite the CKEditor style reset. */
.resourcePicker .dropdown-menu li * {
  cursor: pointer;
}

td.cke_dialog_contents_body {
  /* Make sure the resource type dropdown overflows outside the dialog body
    (otherwise we get a vertical scroll bar when opening the dropdown). */
  overflow: visible;
}

/**
 * Make sure the footer of the entity resource picker modal is always visible because otherwise the user has to scroll a
 * lot when the entity tree is expanded in order to click on the modal buttons to select an entity. See CKEDITOR-317:
 * "Select page" dialog should scroll so that dialog buttons are always visible.
 */
.modal.entity-resource-picker-modal .ckeditor-tree {
  /**
   * modal margin + header + body padding + tree finder + footer = 268px
   * modal margin = 2 x 30px
   * header = 61px
   * body padding = 2 x 15px
   * tree finder = 48px
   * footer = 69px
   */
  max-height: calc(~"100vh - 268px");
  overflow-y: auto;
}

/**
 * Handle the layout and display of the warning message for headerless tables.
 * This message is added by the xwiki-table plugin.
 * Some of the default styles are just overridden by the CKEditor reset.
 */
.cke_dialog_container span.box.warningmessage {
  .alert-warning;
  /* Default warning boxes are not meant to be used in a strict layout like the one of this table dialog.
   * We need an extra customization to avoid breaking this layout. */
  white-space: break-spaces;
  /* By default, the warning is not shown. */
  display: none;
}

/* When the value of the previous field is the one we want to avoid, we show the warning. */
.cke_dialog_container tr:has(select [value=""]:checked) + tr span.box.warningmessage {
  display: unset;
}

/**
 * Link Options Toggle
 */

.linkOptionsToggle > .cke_dialog_ui_labeled_label {
  color: #777;
  cursor: pointer;
}
.linkOptionsToggle .arrow {
  display: inline-block;
  height: 0;
  width: 0;
}
.linkOptionsToggle .arrow-down {
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-top: 4px solid #777;
  margin-bottom: 1px;
}
.linkOptionsToggle .arrow-right {
  border-bottom: 4px solid transparent;
  border-left: 4px solid #777;
  border-top: 4px solid transparent;
  margin-right: 4px;
}

/**
 * Custom tool bar icons (Glyphicon)
 */
a.cke_button.cke_button__xwiki-macro > span.cke_button_icon.cke_button__xwiki-macro_icon,
a.cke_button.cke_button__xwiki-macro-edit > span.cke_button_icon.cke_button__xwiki-macro-edit_icon,
a.cke_button.cke_button__xwiki-link-open > span.cke_button_icon.cke_button__xwiki-link-open_icon,
a.cke_button.cke_button__insert > span.cke_button_icon.cke_button__insert_icon {
  font-family: 'Glyphicons Halflings';
  position: relative;
  top: 1px;
}
.cke_button_icon.cke_button__xwiki-macro_icon::before,
.cke_button_icon.cke_button__xwiki-macro-edit_icon::before,
.cke_button_icon.cke_button__xwiki-link-open_icon::before,
.cke_button_icon.cke_button__insert_icon::before {
  display: inline-block;
  text-align: center;
  width: 16px;
}
.cke_button_icon.cke_button__xwiki-macro_icon::before {
  content: "\e019";
}
.cke_button_icon.cke_button__xwiki-macro-edit_icon::before {
  content: "\e032";
}
.cke_button_icon.cke_button__xwiki-link-open_icon::before {
  content: "\e164";
}
.cke_button_icon.cke_button__insert_icon::before {
  content: "\002b";
}

/**
 * Autocomplete styles
 */
ul.cke_autocomplete_panel {
  border: 1px solid rgba(0, 0, 0, 0.15);
  border-radius: @border-radius-base;
  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.175);
  font: inherit;
  padding: 5px 0;
  width: auto;
  max-width: 324px;
  min-width: 200px;
}
.cke_autocomplete_panel > li.ckeditor-autocomplete-group,
.cke_autocomplete_panel > li.ckeditor-autocomplete-item {
  padding: 5px 20px;
}
.cke_autocomplete_panel > li.ckeditor-autocomplete-group {
  border-top: 1px solid @xwiki-border-color;
  color: @text-muted;
  font-size: smaller;
  margin-top: 9px;
  padding-top: 14px;
}
.cke_autocomplete_panel > li.ckeditor-autocomplete-group h6 {
  font-size: inherit;
  margin: 0;
}
.cke_autocomplete_panel > li.ckeditor-autocomplete-group:first-child {
  border-top: 0 none;
  margin-top: 0;
  padding-top: 5px;
}
.cke_autocomplete_panel > li.ckeditor-autocomplete-group:hover {
  background-color: transparent;
  cursor: inherit;
}
.ckeditor-autocomplete-group h6,
.ckeditor-autocomplete-item-label,
.ckeditor-autocomplete-item-shortcut {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ckeditor-autocomplete-item-head {
  display: flex;
  align-items: center;
}
.ckeditor-autocomplete-item-icon-wrapper {
  display: inline-block;
  height: 14px;
  line-height: 14px;
  margin-right: .5em;
  text-align: center;
  width: 14px;
}
.ckeditor-autocomplete-item-icon-wrapper img {
  border-radius: @border-radius-small;
  max-height: 14px;
  max-width: 14px;
  vertical-align: text-top;
}
.ckeditor-autocomplete-item-preview-wrapper {
  display: flex;
  align-items: center;
  justify-content: space-around;
  height: 64px;
  margin-right: .5em;
  text-align: center;
  vertical-align: middle;
  width: 64px;
}
.ckeditor-autocomplete-centered {
  justify-content: center;
}
.ckeditor-autocomplete-item-preview-wrapper img {
  border-radius: @border-radius-small;
  max-height: 64px;
  max-width: 64px;
  vertical-align: text-top;
}
/* The image still takes some space in all browsers even if there's no source specified. Let's make sure it's hidden.
  See CKEDITOR-389: Missing space in the suggestions that appear while using the autocomplete function on IE 11 */
.ckeditor-autocomplete-item-preview-wrapper img[src=""],
.ckeditor-autocomplete-item-icon-wrapper img[src=""] {
  display: none;
}
.ckeditor-autocomplete-item-label {
  /* Push the shortcut to the right edge of the item. */
  flex-grow: 1;
}
.ckeditor-autocomplete-item-shortcut:not(:empty) {
  background-color: @xwiki-border-color;
  border-radius: @border-radius-base;
  padding: 2px 5px;
  margin-left: .5em;
}
.ckeditor-autocomplete-item-shortcut,
.ckeditor-autocomplete-item-badge,
.ckeditor-autocomplete-item-hint {
  color: @text-muted;
  font-size: smaller;
}
.ckeditor-autocomplete-item-badge {
  background-color: @xwiki-border-color;
  font-weight: normal;
}
.ckeditor-autocomplete-item-hint {
  /* Limit to 3 lines of text (based on line height). */
  max-height: calc(3 * 20em / 14);
  overflow: hidden;
  /* Put the ellipsis at the end of the last line when the text is cut. */
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}
.ckeditor-autocomplete-item-hint:empty {
  margin-top: 0;
}

/**
 * Source mode
 */

.cke_contents > textarea.cke_source {
  box-sizing: border-box;
  color: @text-color;
  font-family: @font-family-monospace;
  font-size: inherit;
  /* Same padding as on the page content. */
  padding: @grid-gutter-width / 2;
}

.cke_contents > textarea.cke_source.cke_editable_inline {
  box-shadow: none;
}

#xwikicontent + .cke_contents > textarea.cke_source.cke_editable_inline {
  /* Don't take the padding and the margin into account when computing the 100% width. */
  box-sizing: content-box;
  /* Make sure the Source area has the same width as the WYSIWYG area. */
  margin-left: -@grid-gutter-width / 2;
  margin-right: -@grid-gutter-width / 2;
}

/**
 * Custom styles to match XWiki's Look & Feel
 */
.cke_chrome,
.cke_chrome > .cke_inner {
  border-radius: @border-radius-base;
}

.cke_chrome > .cke_inner > .cke_top {
  border-top-right-radius: @border-radius-base;
  border-top-left-radius: @border-radius-base;
}

.cke_chrome > .cke_inner > .cke_bottom {
  border-bottom-right-radius: @border-radius-base;
  border-bottom-left-radius: @border-radius-base;
}

a.cke_button,
a.cke_combo_button {
  border-radius: @border-radius-small;
}

.cke_panel,
.cke_dialog_body,
.cke_dialog a.cke_dialog_ui_button,
.cke_dialog input.cke_dialog_ui_input_text,
.cke_dialog select.cke_dialog_ui_input_select,
.cke_dialog fieldset.cke_dialog_ui_fieldset,
.cke_notification {
  border-radius: @border-radius-base;
}

.cke_panel.cke_menu_panel,
.cke_panel.cke_combopanel {
  margin: 2px 0;
}

.cke_dialog_title,
.cke_dialog a.cke_dialog_tab {
  border-top-right-radius: @border-radius-base;
  border-top-left-radius: @border-radius-base;
}

.cke_dialog_contents,
.cke_dialog_footer {
  border-bottom-right-radius: @border-radius-base;
  border-bottom-left-radius: @border-radius-base;
}

/**
 * Custom styles for the in-line editor
 */
.viewbody > .cke_float {
  /* Shift the floating toolbar in order to match the content padding. */
  margin-right: floor((@grid-gutter-width / 2));
  margin-left: ceil((@grid-gutter-width / 2));
}
.cke_float .cke_top {
  border-radius: @border-radius-base;
}

/**
 * Full-screen styles for the in-line editor
 */
body[data-maximized="true"] {
  overflow: hidden;

  .cke_maximize_backdrop,
  .cke_toolBar_active,
  .cke_editable_active,
  .cke_actionBar_active {
    position: fixed !important;
    right: 0 !important;
    left: 0 !important;
  }

  /*
   * The tool bar
   */
  .cke_toolBar_active {
    /* We have to use !important in order to overwrite the in-line styles. */
    display: block !important;
    top: 0 !important;
    /* Above the backdrop, like the editing area. */
    z-index: 9995;
  }

  /*
   * The editing area
   */
  .cke_maximize_backdrop,
  .cke_editable_active {
    background-color: @xwiki-page-content-bg;
  }
  .cke_editable_active {
    box-sizing: border-box !important;
    margin: 0 !important;
    overflow-y: auto !important;
    z-index: 9995;
  }
  .cke_maximize_backdrop {
    top: 0;
    bottom: 0;
    z-index: 99;
  }

  /*
   * The action buttons
   */
  .cke_actionBar_active {
    background-color: @xwiki-background-secondary-color;
    border: 1px solid @xwiki-border-color;
    bottom: 0;
    /* Reduce a bit the padding. */
    padding: .5em;
    z-index: 9995;
  }
}

/*
 * Override the CKEditor reset for the table border color.
 * The default border color from CKEditor is quite lacking on contrast.
 */
.cke_editable.cke_show_borders table.cke_show_border,
.cke_editable.cke_show_borders table.cke_show_border > tr > th,
.cke_editable.cke_show_borders table.cke_show_border > tr > td,
.cke_editable.cke_show_borders table.cke_show_border > thead > tr > th,
.cke_editable.cke_show_borders table.cke_show_border > thead > tr > td,
.cke_editable.cke_show_borders table.cke_show_border > tbody > tr > th,
.cke_editable.cke_show_borders table.cke_show_border > tbody > tr > td,
.cke_editable.cke_show_borders table.cke_show_border > tfoot > tr > th,
.cke_editable.cke_show_borders table.cke_show_border > tfoot > tr > td {
  border-color: @table-border-color;
  border-style: solid;
}

/* CKEditor contains a CSS reset. It works with its own style sheets and does not use the ones in XWiki.
However, we want `.sr-only` from XWiki to still be usable in our CKEditor environment.
We need to redefine the XWiki styles of this class to have better priority than the CKEditor CSS reset.
Without this, the elements with this class are still shown which would be different from the behaviour 
of `.sr-only` anywhere else in XWiki (as described in our doc).
This redefinition allows for a more consistent behaviour of the `.sr-only` class. */
.cke_reset_all .sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/**
 * Overwrite CKEditor's CSS reset in order to fix the icon theme
 */
/* Fixes for Font Awesome */
.cke_reset_all .fa {
  font-family: var(--fa-family ,var(--fa-style-family, "Font Awesome 7 Free"));
  font-weight: var(--fa-style, 900);
}
/* The icons with '-o' suffix need to have a normal font-weight. */
.cke_reset_all .fa.fa-file-o,
.cke_reset_all .fa.fa-envelope-o {
  font-weight: 400;
}
